const T = DICT[LANG] || DICT.zh;
const MANUAL = {
  zh: [
    {k:'states',label:'状态与判断',sections:[
      {h:'运行与存档状态',body:'<ul><li><b>loaded</b>:物理体已加载并参与运行。</li><li><b>stored</b>:磁盘中有条目和有效 holding 指针,但当前未加载。</li><li><b>holding</b>:由 holding chunk 在内存中持有,尚待正常保存流程处理。</li><li><b>orphan</b>:磁盘条目仍在,但没有任何有效 holding 指针,正常流程无法再找到它。</li></ul>'},
      {h:'组合与异常',body:'<ul><li><b>物理组</b>(即依赖组):按 Sable 依赖关系绑定的一组物理体,面板各处统称物理组。删除和恢复以完整物理组为边界。</li><li><b>副本</b>:同一个 UUID 在磁盘中出现多个条目,不代表内容一定相同。</li><li><b>疑似克隆</b>:不同 UUID 命中相同外形摘要,仅用于提示,不等同于确认重复。</li></ul>'},
      {h:'常驻票与常驻意图',body:'<ul><li><b>常驻票</b>:sable 的 force-load 加载票。常驻加载 = 面板给完整物理组挂票,让它保持加载。</li><li><b>常驻意图</b>:面板记住的「该组应当常驻」的意愿,写在配置目录里、跨重启保持。票丢了但意图还在,就是「常驻掉线」徽章。</li></ul>'},
      {h:'疑似克隆条件',body:'<p>命名体比较完整名称、方块数和取整后的包围盒;未命名体还要求不少于 50 块,再比较方块数和取整包围盒。该判断不比较体素、方块组成、维度和位置,因此可能误报,也可能漏报。</p>'}
    ]},
    {k:'cleanup',label:'清理判断',sections:[
      {h:'推荐删除',body:'<p>必须同时满足:整组无名称、总方块数低于动态阈值、方块种类低于动态阈值、方块实体数低于动态阈值、容器全空、无人乘坐、没有第三方数据。阈值来自 <code>config/sablepanel/sablepanel-server.json</code>。</p>'},
      {h:'保护条件',body:'<p>物理组中任一成员有名称、玩家乘坐、第三方数据、非空容器,或整组达到任一保护阈值,就不会进入推荐删除。副本和疑似克隆只是异常提示,不会单独证明内容可删。</p>'}
    ]},
    {k:'operations',label:'操作',sections:[
      {h:'日常操作',body:'<ul><li><b>重扫</b>:立即重建磁盘索引;后台也会每 120 秒自动扫描。</li><li><b>传送</b>:坐标指结构包围盒的<b>底面中心</b>(目的 y=100 表示结构底部落在 y=100)。未加载体会先强制加载;孤儿会先尝试连同依赖一起收养。</li><li><b>常驻加载</b>:只让完整物理组保持加载并自然运行,不清速度、不固定物理、不暂停 tick;取消后保存当前状态并卸载到磁盘。</li><li><b>暂停物理</b>:先用引擎固定约束锁住完整物理组,再清除全部线速度和角速度;方块实体仍正常 tick。</li><li><b>暂停 tick</b>:只停止完整物理组的方块实体 tick,物理仍自然运行。</li><li><b>收养</b>:重建 holding 指针并接回加载管线,不删除或改写原有物理体条目。</li><li><b>删除</b>:按完整物理组执行,严格验收成功后才提交回收站备份。</li><li><b>批量操作</b>:勾选会跨筛选保留;批量删除仍会按物理组去重并逐组验收。</li></ul>'},
      {h:'副本处理',body:'<p>打开后按完整物理组、holding 位置和当前活动指针列出候选版本,并提供只读预览。只有依赖完整的版本可以设为主版本;未选版本会进入旧版本回收站,不会自动晋升。无法组成完整物理组的条目只能隔离,不能直接恢复。</p>'}
    ]},
    {k:'recycle',label:'回收站',sections:[
      {h:'何时进入回收站',body:'<p>删除前会暂存完整物理组备份;磁盘条目和 holding 指针通过删除后验收时记为可恢复。删除或自动回滚中断时,完整备份会记为删除未完成,不再隐藏。回收站不会自动清除任何组,容量不足时请在列表中多选并彻底删除。</p>'},
      {h:'恢复与容量',body:'<ul><li>恢复始终恢复完整物理组,并在保存的维度和位置重新加载;旧版本不会覆盖世界中已有的同 UUID 物理体。</li><li><b>可恢复</b>表示删除成功且备份可用;最新版本的<b>删除未完成</b>会先清除同 UUID 残留再从快照重建整组;<b>已恢复</b>表示该记录已经成功执行过恢复。</li><li>容量按实际备份文件计数。面板不会自动淘汰任何回收组;达到或超过上限时,新删除会在执行前被拒绝,需人工多选并彻底删除。</li></ul>'}
    ]},
    {k:'performance',label:'性能数据',sections:[
      {h:'曲线口径',body:'<ul><li><b>各维度物理引擎</b>:该维度物理步进耗时按服务器 tick 折算的毫秒值。</li><li><b>物理体逻辑</b>:所有已加载物理体 Java 逻辑每 tick 的采样合计,不包含服务器其它 mod。</li></ul>'},
      {h:'窗口与交互',body:'<p>数据保存在服务端内存里,窗口固定为最近 15 分钟、每秒一个点,重启后从零开始。预设按钮只切换本地显示的窗口长度;悬停查看精确时间和各曲线值。</p>'}
    ]},
    {k:'maintenance',label:'面板维护',sections:[
      {h:'口令与监听',body:'<p>访问口令作为页面密码保存在浏览器当前设备中;维护卡片修改后会同步到当前集群。网页默认使用 <code>webPort=25580</code>,TLS 数据接口默认使用 <code>apiPort=25581</code>;配置位于 <code>config/sablepanel/sablepanel-server.json</code>。</p>'},
      {h:'集群',body:'<p>同机且使用同一 <code>apiPort</code> 的实例组成面板集群。先占用数据端口的实例成为 HOST 并按 <code>webPort</code> 托管页面,其它实例通过回环地址注册为 PEER 并采纳 HOST 口令;顶部服务器选择器只切换查看目标,不迁移物理体数据。</p>'}
    ]}
  ],
  en: [
    {k:'states',label:'States & judgement',sections:[
      {h:'Runtime and archive states',body:'<ul><li><b>loaded</b>: the body is loaded and running.</li><li><b>stored</b>: a disk entry with a valid holding pointer exists, but the body is not loaded.</li><li><b>holding</b>: kept in memory by a holding chunk, awaiting the normal save flow.</li><li><b>orphan</b>: the disk entry remains, but no valid holding pointer points at it — the normal flow can no longer find it.</li></ul>'},
      {h:'Groups and anomalies',body:'<ul><li><b>Physics group</b> (a.k.a. dependency group): a set of bodies bound by sable dependencies; the panel calls it a physics group everywhere. Deletion and restore act on whole physics groups.</li><li><b>Copy</b>: the same UUID appears in several disk entries — content is not necessarily identical.</li><li><b>Suspected clone</b>: different UUIDs share the same shape digest; a hint only, not confirmed duplication.</li></ul>'},
      {h:'Force-load tickets and intents',body:'<ul><li><b>Force-load ticket</b>: a sable loading ticket. Force-load = the panel attaches tickets to the whole physics group so it stays loaded.</li><li><b>Force-load intent</b>: the panel\'s recorded wish that the group should stay force-loaded, stored in the config directory across restarts. Ticket gone but intent still there = the "Force-load lost" badge.</li></ul>'},
      {h:'Suspected clone criteria',body:'<p>Named bodies compare full name, block count and rounded bounding box; unnamed bodies additionally require ≥50 blocks. The check ignores voxels, block composition, dimension and position, so both false positives and misses are possible.</p>'}
    ]},
    {k:'cleanup',label:'Cleanup judgement',sections:[
      {h:'Cleanup candidates',body:'<p>All of the following must hold: the whole group is unnamed, total blocks below the dynamic threshold, block types below the threshold, block entities below the threshold, all containers empty, nobody riding, no third-party data. Thresholds come from <code>config/sablepanel/sablepanel-server.json</code>.</p>'},
      {h:'Protection',body:'<p>If any member has a name, riders, third-party data or non-empty containers, or the group reaches any protection threshold, it never becomes a cleanup candidate. Copies and suspected clones are anomaly hints only and never justify deletion by themselves.</p>'}
    ]},
    {k:'operations',label:'Operations',sections:[
      {h:'Everyday operations',body:'<ul><li><b>Rescan</b>: rebuild the disk index now; a background scan also runs every 120 s.</li><li><b>Teleport</b>: coordinates refer to the <b>bottom centre</b> of the bounding box (y=100 means the structure\'s bottom lands at y=100). Unloaded bodies are force-loaded first; orphans are adopted together with their dependencies.</li><li><b>Force-load</b>: keeps the whole physics group loaded and running naturally — no velocity clearing, no pinning, no ticking pause; cancelling saves the current state and unloads to disk.</li><li><b>Pause physics</b>: pins the whole physics group with engine fixed constraints, then clears all velocity; block entities keep ticking.</li><li><b>Pause ticking</b>: stops block-entity ticking for the whole physics group only; physics keeps running.</li><li><b>Adopt</b>: rebuilds holding pointers and re-attaches to the loading pipeline without deleting or rewriting entries.</li><li><b>Delete</b>: acts on whole physics groups; the recycle-bin backup commits only after strict verification.</li><li><b>Batch operations</b>: selection survives filter changes; batch delete still deduplicates by physics group and verifies per group.</li></ul>'},
      {h:'Managing copies',body:'<p>Lists candidate versions by whole physics group, holding position and current active pointer, with a read-only preview. Only versions with complete dependencies can become primary; unselected versions go to the old-version recycle bin and are never promoted automatically. Entries that cannot form a complete physics group can only be quarantined, not restored directly.</p>'}
    ]},
    {k:'recycle',label:'Recycle bin',sections:[
      {h:'When things enter the bin',body:'<p>A whole-physics-group backup is staged before deletion; it becomes restorable once the post-delete verification of disk entries and holding pointers passes. If deletion or auto-rollback is interrupted, the full backup is marked "delete incomplete" instead of being hidden. The bin never auto-purges; when full, multi-select and purge manually.</p>'},
      {h:'Restore and capacity',body:'<ul><li>Restore always restores the whole physics group at the saved dimension and position; old versions never overwrite same-UUID bodies already in the world.</li><li><b>Restorable</b> means deletion succeeded and the backup is usable; a latest-version <b>delete incomplete</b> clears same-UUID remains first, then rebuilds the group from the snapshot; <b>restored</b> means the record has already been restored successfully.</li><li>Capacity counts actual backup files. The panel never evicts recycle groups; at or above the limit, new deletions are rejected up front — multi-select and purge manually.</li></ul>'}
    ]},
    {k:'performance',label:'Performance data',sections:[
      {h:'What the curves mean',body:'<ul><li><b>Per-dimension physics engine</b>: physics stepping time of that dimension in milliseconds per server tick.</li><li><b>Body logic</b>: sampled per-tick Java logic of all loaded bodies combined; other mods are not included.</li></ul>'},
      {h:'Window and interaction',body:'<p>Data lives in server memory: a fixed 15-minute window, one point per second, starting fresh after restarts. Preset buttons only change the locally displayed window; hover for exact times and values.</p>'}
    ]},
    {k:'maintenance',label:'Panel maintenance',sections:[
      {h:'Token and ports',body:'<p>The access token is stored in this browser as the page password; changing it in the Maintenance card syncs the current cluster. The web page defaults to <code>webPort=25580</code>, the TLS data API to <code>apiPort=25581</code>; config lives in <code>config/sablepanel/sablepanel-server.json</code>.</p>'},
      {h:'Cluster',body:'<p>Instances on the same machine sharing one <code>apiPort</code> form a panel cluster. The first to claim the data port becomes HOST and serves the page on <code>webPort</code>; the rest register via loopback as PEER and adopt the HOST token. The server picker at the top only switches the viewing target — no body data migrates.</p>'},
      {h:'Language',body:'<p>The UI language toggle reloads the page. Job operation names, job logs and warnings are recorded server-side in Chinese at execution time and do not switch with the UI language.</p>'}
    ]}
  ]
};
/* 静态标签覆写:HTML 写中文兜底,非中文语言启动时统一替换(main.js 启动序列调用) */
function applyStaticI18n(){
  if (LANG === 'zh') return;
  document.documentElement.lang = LANG;
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const v = T[el.dataset.i18n]; if (typeof v === 'string') el.textContent = v;
  });
  document.querySelectorAll('[data-i18n-title]').forEach(el => {
    const v = T[el.dataset.i18nTitle]; if (typeof v === 'string') el.title = v;
  });
  document.querySelectorAll('[data-i18n-ph]').forEach(el => {
    const v = T[el.dataset.i18nPh]; if (typeof v === 'string') el.placeholder = v;
  });
  document.querySelectorAll('[data-i18n-aria]').forEach(el => {
    const v = T[el.dataset.i18nAria]; if (typeof v === 'string') el.setAttribute('aria-label', v);
  });
}
function toggleLang(){
  try { localStorage.setItem('spLang', LANG === 'zh' ? 'en' : 'zh'); } catch (ignored) {}
  location.reload();
}
function fmt(n){ return Number(n).toLocaleString('en-US'); }
/* 时间戳(ms)三种口径:时刻/日期/完整。图表横轴的 2-digit 紧凑格式是刻意的第四种,留在 chart.js */
function fmtTime(ms){ return new Date(ms).toLocaleTimeString(); }
function fmtDate(ms){ return new Date(ms).toLocaleDateString(); }
function fmtDateTime(ms){ return new Date(ms).toLocaleString(); }
function fmtBytes(value){
  let size=Math.max(0,Number(value)||0), unit=0;
  const units=['B','KiB','MiB','GiB','TiB'];
  while(size>=1024&&unit<units.length-1){ size/=1024; unit++; }
  return `${size.toFixed(unit===0||size>=100?0:size>=10?1:2)} ${units[unit]}`;
}
